        <?php if ($portfolio['evidence']): ?><div class="evidence-list evidence-manage-list" data-evidence-list><?php foreach ($portfolio['evidence'] as $item): ?><article class="evidence-row" draggable="true" data-evidence-item data-evidence-id="<?= (int)$item['id'] ?>" data-evidence-mime="<?= e($item['mime_type']) ?>"><span class="evidence-drag-handle" title="اسحب لإعادة الترتيب">⠿</span><span class="evidence-type-icon"><?= !empty($item['source_url'])?'↗':(str_starts_with($item['mime_type'],'image/')?'▧':'▤') ?></span><div><strong><?= e($item['title']) ?></strong><?php if (!empty($item['evidence_type'])): ?><span class="evidence-subtype-badge"><?= e($item['evidence_type']) ?></span><?php endif; ?><small><?= e($item['section_title']??'غير مربوط') ?> · <?= !empty($item['source_url'])?($item['source_kind']==='drive'?'Google Drive':'رابط خارجي'):number_format((int)$item['file_size']/1024,0).' كيلوبايت' ?></small></div><?php if (str_starts_with($item['mime_type'],'image/') || $item['mime_type']==='application/pdf'): ?><button type="button" class="text-button evidence-preview-trigger" data-evidence-preview="/evidence/<?= (int)$item['id'] ?>/preview" data-evidence-title="<?= e($item['title']) ?>">استعراض</button><?php endif; ?><a href="/evidence/<?= (int)$item['id'] ?>/download" target="_blank" rel="noopener noreferrer"><?= !empty($item['source_url'])?'فتح الرابط':'تنزيل' ?></a><form method="post" action="/evidence/<?= (int)$item['id'] ?>/visibility"><?= csrf_field() ?><input type="hidden" name="visibility" value="<?= $item['visibility']==='public'?'private':'public' ?>"><button type="submit" class="text-button"><?= $item['visibility']==='public'?'إخفاء':'إتاحة' ?></button></form><form method="post" action="/evidence/<?= (int)$item['id'] ?>/delete" data-confirm="هل تريد حذف هذا الدليل نهائيًا؟"><?= csrf_field() ?><button class="text-button danger-text" type="submit">حذف</button></form><?php if (str_starts_with($item['mime_type'],'image/') || $item['mime_type']==='application/pdf'): ?><div class="ocr-inline-tools"><button type="button" class="text-button" data-browser-ocr data-ocr-url="/evidence/<?= (int)$item['id'] ?>/download" data-ocr-type="<?= e($item['mime_type']) ?>">استخراج النص في المتصفح</button><div class="ocr-result-panel" data-ocr-panel hidden><p data-ocr-status aria-live="polite">يُعالج الملف على جهازك فقط؛ لا يُرسل تلقائيًا إلى أي مساعد.</p><textarea rows="6" data-ocr-text aria-label="النص المستخرج للمراجعة"></textarea><button type="button" class="button button-quiet" data-ocr-copy>نسخ النص</button></div></div><?php endif; ?></article><?php endforeach; ?></div><?php else: ?><p class="empty-note">لا توجد مرفقات بعد.</p><?php endif; ?>
        <form method="post" action="/evidence/reorder" class="evidence-reorder-form" data-evidence-reorder><?= csrf_field() ?><div data-evidence-order-fields></div><span>اسحب الأدلة والصور لترتيبها تلقائيًا في ملفك</span><button class="button button-outline-navy" type="submit">حفظ ترتيب الأدلة</button></form>
        <form class="upload-form" method="post" action="/evidence/upload" enctype="multipart/form-data" data-upload-form data-user-role="<?= e($currentUser['role']??'student') ?>"><?= csrf_field() ?><div class="upload-fields"><label class="field"><span><?= ($currentUser['role']??'')==='teacher'?'العنصر':'القسم المرتبط' ?></span><select name="section_id" required data-evidence-main-section><?php foreach ($sections as $section): if (($currentUser['role']??'')==='teacher' && !empty($section['parent_id'])) continue; ?><option value="<?= (int)$section['id'] ?>"><?= e($section['title']) ?></option><?php endforeach; ?></select></label><?php if (($currentUser['role']??'')==='teacher'): ?><label class="field evidence-type-field"><span>نوع الشاهد</span><select name="evidence_type" required data-evidence-type-select><option value="">اختر نوع الشاهد</option><?php foreach ($sections as $mainSection): if (!empty($mainSection['parent_id'])) continue; foreach (($teacherWitnessCatalog[$mainSection['title']]??[]) as $witnessTitle): ?><option value="<?= e($witnessTitle) ?>" data-main-id="<?= (int)$mainSection['id'] ?>" hidden><?= e($witnessTitle) ?></option><?php endforeach; endforeach; ?><option value="__other__">شاهد آخر…</option></select></label><label class="field evidence-custom-type" data-evidence-custom-wrap hidden><span>اكتب نوع الشاهد</span><input name="evidence_type_custom" maxlength="120" placeholder="اسم الشاهد"></label><?php endif; ?><label class="field"><span>اسم الملف أو وصفه</span><input name="title" maxlength="120" placeholder="مثال: تقرير الزيارة الصفية"></label><label class="field"><span>تاريخ الدليل</span><input type="date" name="evidence_date"></label><label class="field"><span>وسوم</span><input name="tags" maxlength="200" placeholder="تخطيط، تقويم، مشروع"></label></div><label class="field"><span>وصف مختصر</span><textarea name="description" rows="2" maxlength="1000" placeholder="ما الذي يوضحه هذا الدليل؟"></textarea></label><label class="field"><span>ربط بمهارة أو مؤشر (اختياري)</span><input name="competency" maxlength="120" placeholder="مثال: تنويع استراتيجيات التدريس"></label><div class="camera-scanner" data-camera-scanner><div class="camera-scanner-copy"><strong>ماسح الشواهد بالكاميرا</strong><span>التقط صورة، حسّن الإضاءة والتباين، ثم ارفعها كدليل. يعمل مباشرة من المتصفح دون Docker.</span></div><button type="button" class="button button-outline-navy" data-camera-open>فتح الكاميرا</button><div class="camera-scanner-panel" data-camera-panel hidden><video data-camera-video autoplay playsinline muted></video><canvas data-camera-canvas hidden></canvas><div class="camera-scanner-actions"><button type="button" class="button button-gold" data-camera-capture>التقاط</button><button type="button" class="button button-quiet" data-camera-enhance>تحسين المستند</button><button type="button" class="button button-quiet" data-camera-close>إغلاق</button></div><small data-camera-status>اسمح للمتصفح باستخدام الكاميرا لالتقاط الشاهد.</small></div></div><label class="field evidence-source-url"><span>أو أضف الشاهد من رابط</span><input type="url" name="source_url" maxlength="2000" placeholder="https://… أو رابط Google Drive"><small>لن تُنزّل المنصة الرابط؛ يفتح في نافذة جديدة ويحافظ على صلاحيات Google Drive.</small></label><div class="evidence-source-divider">أو ارفع ملفًا من جهازك</div><label class="file-drop"><input type="file" name="evidence_file" accept="image/*,.pdf,.doc,.docx,.ppt,.pptx,.xls,.xlsx,.txt" capture="environment" data-file-preview><span class="file-drop-icon">＋</span><strong>اختر ملفًا أو التقط صورة بالكاميرا</strong><small>صور، PDF، Word، PowerPoint، Excel أو نص · حتى 8 ميغابايت</small><span data-file-name>لم يُحدد ملف بعد</span></label><p class="helper-note">لا تُرسل الملفات تلقائيًا إلى الذكاء الاصطناعي. راجع الصور بحثًا عن أسماء الطلاب أو أرقامهم قبل إتاحتها.</p><button class="button button-navy" type="submit">رفع الدليل إلى مساحتي</button></form>
    </section>
</section>
